import sqlite3
import logging
from contextlib import closing
import stripe
from agents import function_tool

logger = logging.getLogger(__name__)


@function_tool
def cancel_freight_booking_with_refund(booking_id: str, cancellation_fee_cents: int = 0, db_path: str = "logistics.db") -> str:
    if cancellation_fee_cents < 0:
        return "Cancellation fee cannot be negative"
    with closing(sqlite3.connect(db_path)) as conn:
        conn.row_factory = sqlite3.Row
        with conn:
            booking = conn.execute(
                "SELECT id, status, payment_intent_id, amount_cents FROM freight_bookings WHERE id = ?",
                (booking_id,),
            ).fetchone()
            if booking is None:
                return f"Booking {booking_id} not found"
            if booking["status"] in ("picked_up", "in_transit", "delivered"):
                return f"Booking {booking_id} cannot be cancelled while {booking['status']}"
            if booking["status"] == "cancelled":
                return f"Booking {booking_id} is already cancelled"
            refund_amount = booking["amount_cents"] - cancellation_fee_cents
            if refund_amount <= 0:
                return "Cancellation fee exceeds the booking amount"
            try:
                refund = stripe.Refund.create(
                    payment_intent=booking["payment_intent_id"],
                    amount=refund_amount,
                    metadata={"booking_id": booking_id},
                )
            except stripe.error.StripeError as exc:
                logger.error("Refund failed for %s: %s", booking_id, exc)
                return f"Refund failed: {exc}"
            deleted = conn.execute(
                "DELETE FROM pickup_schedules WHERE booking_id = ?",
                (booking_id,),
            ).rowcount
            conn.execute(
                "UPDATE freight_bookings SET status = 'cancelled' WHERE id = ?",
                (booking_id,),
            )
    logger.info("Cancelled booking %s, refund %s", booking_id, refund.id)
    return (
        f"Booking {booking_id} cancelled. Refunded {refund_amount} cents "
        f"(refund {refund.id}); removed {deleted} pickup schedule entries."
    )

import sqlite3
from agents import function_tool


@function_tool
def grant_warehouse_access_role(uid: str, wh: str, role: str) -> str:
    ok = {"viewer", "picker", "manager"}
    if role not in ok:
        return f"Invalid role {role}"
    c = sqlite3.connect("logistics.db")
    try:
        c.execute(
            "INSERT INTO warehouse_roles (user_id, warehouse_id, role) VALUES (?, ?, ?) "
            "ON CONFLICT(user_id, warehouse_id) DO UPDATE SET role = excluded.role",
            (uid, wh, role),
        )
        c.commit()
    finally:
        c.close()
    return f"User {uid} now has role {role} at warehouse {wh}"
